import React from 'react';
import { useTranslation } from 'react-i18next';

const Contact = () => {
  const { t } = useTranslation();
  const contactMethods = t('contact.methods', { returnObjects: true });
  const asideItems = t('contact.asideItems', { returnObjects: true });

  return (
    <main className="page-shell">
      <header className="page-header">
        <span className="eyebrow">{t('contact.eyebrow')}</span>
        <h1 className="page-title">{t('contact.title')}</h1>
        <p className="page-lead">{t('contact.lead')}</p>
      </header>

      <section className="contact-layout">
        <div className="contact-grid">
          {contactMethods.map((method, index) => (
            <article key={`${method.title}-${index}`} className="contact-method panel panel--pad">
              <p className="contact-method__label">{method.label}</p>
              <h2 className="contact-method__title">{method.title}</h2>
              <p className="contact-method__text">{method.description}</p>
              <a
                href={method.link}
                target="_blank"
                rel="noopener noreferrer"
                className="btn btn-secondary"
              >
                {method.linkText}
              </a>
            </article>
          ))}
        </div>

        <aside className="panel panel--pad contact-aside">
          <p className="panel-kicker">{t('contact.asideKicker')}</p>
          <ul className="bullet-list">
            {asideItems.map((item) => (
              <li key={item}>{item}</li>
            ))}
          </ul>

          <a className="btn btn-primary" href="mailto:ayrtonarc@gmail.com">{t('contact.sendEmail')}</a>
        </aside>
      </section>
    </main>
  );
};

export default Contact;

